static final class Tag {
    private final String name;

    Tag(String name) {
        this.name = name;
    }

    String name() {
        return name;
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof Tag other && other.name.equalsIgnoreCase(name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name);
    }
}

